using System.Net;
using System.Net.Http.Headers;
using System.Net.Http.Json;
using BARANG.Core.Domain.Catalog;
using BARANG.Core.Domain.Customers;
using BARANG.Core.Domain.Orders;
using BARANG.Core.Domain.Organization;
using BARANG.Core.Infrastructure.Persistence;
using Xunit;

namespace BARANG.Core.IntegrationTests.Database;

[Collection(PostgreSqlDatabaseFixture.CollectionName)]
public sealed class BusinessProfileApiTests(PostgreSqlDatabaseFixture database)
{
    [Fact]
    public async Task ProfilesPersistConflictFreezeAndRemainCompanyIsolated()
    {
        CancellationToken ct=TestContext.Current.CancellationToken;await database.ResetAsync(ct);Guid company=Guid.NewGuid(),other=Guid.NewGuid(),branch=Guid.NewGuid(),customer=Guid.NewGuid();DateTimeOffset now=DateTimeOffset.UtcNow;Product product;ProductVariant variant;Equipment printer,press;
        await using(CoreDbContext db=database.CreateAdministrationCoreDbContext())
        {
            db.Companies.AddRange(Company.Create(company,"PROFILE_A","Profile A",now).Value,Company.Create(other,"PROFILE_B","Profile B",now).Value);db.Branches.Add(Branch.Create(branch,company,"MAIN","Main",now).Value);db.Customers.Add(Customer.Create(customer,company,"C-BA",CustomerType.Person,"Walk-in","Ali","Test",null,"001",null,null,"09120000000",null,null,null,now).Value);
            product=Product.Create(Guid.NewGuid(),company,"P-BA","Technical Shirt",null,"APPAREL","PCS",now).Value;variant=ProductVariant.Create(Guid.NewGuid(),product,"SKU-BA","Blue Large",null,"L","BLUE",now).Value;printer=Equipment.Create(Guid.NewGuid(),company,"PR-1","Printer","PRINTER","AVAILABLE",null,null,null,null,null,null,now).Value;press=Equipment.Create(Guid.NewGuid(),company,"HP-1","Heat Press","HEAT_PRESS","AVAILABLE",null,null,null,null,null,null,now).Value;db.AddRange(product,variant,printer,press);await db.SaveChangesAsync(ct);
        }
        await using PostgreSqlCoreApiFactory factory=new(database.ConnectionString);using HttpClient client=factory.CreateClient();using HttpRequestMessage bootstrap=new(HttpMethod.Post,"/api/v1/security/bootstrap"){Content=JsonContent.Create(new{companyId=company,username="profile-admin",displayName="Profile Admin",password="StrongProfilePassword123"})};bootstrap.Headers.Add("X-Bootstrap-Secret","test-bootstrap-secret-123456789");(await client.SendAsync(bootstrap,ct)).EnsureSuccessStatusCode();Login login=await Read<Login>(await client.PostAsJsonAsync("/api/v1/auth/login",new{username="profile-admin",password="StrongProfilePassword123"},ct),ct);await Read<object>(await client.SendAsync(Req(HttpMethod.Post,"/api/v1/auth/me/company",login.AccessToken,null,new{companyId=company}),ct),ct);
        CustomerProfile cp=await Read<CustomerProfile>(await client.SendAsync(Req(HttpMethod.Put,$"/api/v1/customers/{customer}/business-profile",login.AccessToken,company,new{dateOfBirth="1990-01-02",economicCode="EC-1",creditLimit=1000,paymentTermsDays=30,businessDetails="walk-in"}),ct),ct);Assert.Equal("EC-1",cp.EconomicCode);
        ProductProfile pp=await Read<ProductProfile>(await client.SendAsync(Req(HttpMethod.Put,$"/api/v1/products/{product.Id}/technical-profile",login.AccessToken,company,new{productVariantId=variant.Id,brandCode="ACME",materialCode="COTTON",genderCode="UNISEX",fitCode="REGULAR",styleCode="TEE",technicalAttributes="180 GSM"}),ct),ct);Assert.Equal("COTTON",pp.MaterialCode);DateOnly from=new(2026,1,1);await Read<object>(await client.SendAsync(Req(HttpMethod.Post,"/api/v1/pricing/tariffs",login.AccessToken,company,new{tariffType=0,code="RAW",productVariantId=variant.Id,amount=10,currencyCode="IRR",validFrom=from}),ct),ct);await Read<object>(await client.SendAsync(Req(HttpMethod.Post,"/api/v1/pricing/tariffs",login.AccessToken,company,new{tariffType=1,code="FRONT_SCREEN",printPositionCode="FRONT",printMethodCode="SCREEN",amount=3,currencyCode="IRR",validFrom=from}),ct),ct);await Read<object>(await client.SendAsync(Req(HttpMethod.Post,"/api/v1/pricing/tariffs",login.AccessToken,company,new{tariffType=2,code="DEFAULT",amount=0,currencyCode="IRR",validFrom=from}),ct),ct);await Read<object>(await client.SendAsync(Req(HttpMethod.Post,"/api/v1/pricing/tariffs",login.AccessToken,company,new{tariffType=3,code="DEFAULT",amount=0,currencyCode="IRR",validFrom=from}),ct),ct);await Read<object>(await client.SendAsync(Req(HttpMethod.Post,"/api/v1/pricing/tax-rules",login.AccessToken,company,new{code="DEFAULT",ratePercent=0,isExempt=true,validFrom=from}),ct),ct);
        using(HttpResponseMessage stale=await client.SendAsync(Req(HttpMethod.Put,$"/api/v1/products/{product.Id}/technical-profile",login.AccessToken,company,new{productVariantId=variant.Id,brandCode="STALE",version=99}),ct))Assert.Equal(HttpStatusCode.Conflict,stale.StatusCode);
        OrderView draft=await Read<OrderView>(await client.SendAsync(Req(HttpMethod.Post,"/api/v1/orders",login.AccessToken,company,new{branchId=branch,customerId=customer,source="Internal",orderDate="2026-09-01"}),ct),ct);OrderItemView item=await Read<OrderItemView>(await client.SendAsync(Req(HttpMethod.Post,$"/api/v1/orders/{draft.Id}/items",login.AccessToken,company,new{productId=product.Id,productVariantId=variant.Id,quantity=2}),ct),ct);PrintView print=await Read<PrintView>(await client.SendAsync(Req(HttpMethod.Post,$"/api/v1/orders/{draft.Id}/items/{item.Id}/print-operations",login.AccessToken,company,new{sequence=1,printPositionCode="FRONT",printMethodCode="SCREEN",width=20,height=30}),ct),ct);
        await Read<object>(await client.SendAsync(Req(HttpMethod.Put,$"/api/v1/orders/{draft.Id}/business-profile",login.AccessToken,company,new{shippingMethodCode="PICKUP",packagingTypeCode="STANDARD",includeInvoiceInPackage=true,orderTypeCode="WALK_IN",notes="Counter sale"}),ct),ct);PrintProfile technical=await Read<PrintProfile>(await client.SendAsync(Req(HttpMethod.Put,$"/api/v1/order-print-operations/{print.Id}/technical-profile",login.AccessToken,company,new{directionCode="PORTRAIT",printSizeCode="CUSTOM",printCount=2,printerEquipmentId=printer.Id,heatPressEquipmentId=press.Id,specifications="White underbase"}),ct),ct);Assert.Equal(2,technical.PrintCount);
        draft=await Read<OrderView>(await client.SendAsync(Req(HttpMethod.Get,$"/api/v1/orders/{draft.Id}",login.AccessToken,company),ct),ct);await Read<OrderView>(await client.SendAsync(Req(HttpMethod.Post,$"/api/v1/orders/{draft.Id}/submit",login.AccessToken,company,new{version=draft.Version}),ct),ct);
        await using(CoreDbContext db=database.CreateAdministrationCoreDbContext()){var snapshot=await Microsoft.EntityFrameworkCore.EntityFrameworkQueryableExtensions.SingleAsync(Microsoft.EntityFrameworkCore.EntityFrameworkQueryableExtensions.IgnoreQueryFilters(db.OrderItemTechnicalSnapshots),x=>x.OrderItemId==item.Id,ct);Assert.Equal("COTTON",snapshot.MaterialCode);Assert.True(await Microsoft.EntityFrameworkCore.EntityFrameworkQueryableExtensions.AnyAsync(Microsoft.EntityFrameworkCore.EntityFrameworkQueryableExtensions.IgnoreQueryFilters(db.WorkflowInstances),x=>x.OrderId==draft.Id,ct));}
        using(HttpResponseMessage locked=await client.SendAsync(Req(HttpMethod.Put,$"/api/v1/orders/{draft.Id}/business-profile",login.AccessToken,company,new{shippingMethodCode="POST",version=1}),ct))Assert.Equal(HttpStatusCode.UnprocessableEntity,locked.StatusCode);using(HttpResponseMessage denied=await client.SendAsync(Req(HttpMethod.Get,$"/api/v1/customers/{customer}/business-profile",login.AccessToken,other),ct))Assert.Equal(HttpStatusCode.Forbidden,denied.StatusCode);
    }
    private static HttpRequestMessage Req(HttpMethod method,string uri,string token,Guid? company,object? body=null){HttpRequestMessage r=new(method,uri);r.Headers.Authorization=new AuthenticationHeaderValue("Bearer",token);if(company is not null)r.Headers.Add("X-Company-ID",company.ToString());if(body is not null)r.Content=JsonContent.Create(body);return r;}private static async Task<T>Read<T>(HttpResponseMessage response,CancellationToken ct){using(response){string text=await response.Content.ReadAsStringAsync(ct);Assert.True(response.IsSuccessStatusCode,$"{response.StatusCode}: {text}");return(await response.Content.ReadFromJsonAsync<T>(ct))!;}}
    private sealed record Login(string AccessToken);private sealed record CustomerProfile(string EconomicCode);private sealed record ProductProfile(string MaterialCode);private sealed record PrintProfile(int PrintCount);private sealed record PrintView(Guid Id);private sealed record OrderItemView(Guid Id);private sealed record OrderView(Guid Id,long Version);
}
